print "        if (last_free_block) {";
print "          last_free_block[1] = (value*)p;";
print "          last_free_block = p;";
print "        } else {";
print "          /* first free block in this pool's freelist */";
print "          a->next_obj = (value*)p;";
print "          last_free_block = p;";
print "        }";
print "";
print "        /* advance by the current block's size (as before) */";
print "        p += wh * Wosize_hd(hd);";
next}
NR>646{print}
AWK
awk -f /tmp/patch.awk /app/ocaml/runtime/shared_heap.c > /tmp/shared_heap.c.new && mv /tmp/shared_heap.c.new /app/ocaml/runtime/shared_heap.c'

